console.log("ROLE:", role);
import { useEffect, useState } from "react";
import { getBooks, deleteBook } from "../services/api";
import { useNavigate } from "react-router-dom";
import {
  Table, TableBody, TableCell, TableHead, TableRow,
  Button, Container, Typography, TextField, Box,
  Select, MenuItem, Pagination
} from "@mui/material";


const PAGE_SIZE = 10;

export default function BookTable({ role }) {
  const [books, setBooks] = useState([]);
  const [search, setSearch] = useState("");
  const [sortBy, setSortBy] = useState("title");
  const [page, setPage] = useState(1);

  const navigate = useNavigate();

  const loadBooks = async () => {
    const res = await getBooks();
    setBooks(res.data);
  };

  useEffect(() => {
    loadBooks();
  }, []);

  // 🔍 Search
  let filtered = books.filter(
    (b) =>
      b.title.toLowerCase().includes(search.toLowerCase()) ||
      b.author.toLowerCase().includes(search.toLowerCase())
  );

  // 🔃 Sorting
  filtered.sort((a, b) =>
    (a[sortBy] || "").localeCompare(b[sortBy] || "")
  );

  // 📄 Pagination
  const totalPages = Math.ceil(filtered.length / PAGE_SIZE);
  const paginatedBooks = filtered.slice(
    (page - 1) * PAGE_SIZE,
    page * PAGE_SIZE
  );

  return (
    <Container maxWidth="xl" sx={{ mt: 5 }}>
      <Typography variant="h4" align="center">
        📚 Book Inventory
      </Typography>

      <Box sx={{ display: "flex", gap: 2, my: 3 }}>
        <TextField
          fullWidth
          label="Search by title or author"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />

        <Select value={sortBy} onChange={(e) => setSortBy(e.target.value)}>
          <MenuItem value="title">Sort by Title</MenuItem>
          <MenuItem value="author">Sort by Author</MenuItem>
          <MenuItem value="publishedDate">Sort by Published Date</MenuItem>
        </Select>

        {role === "admin" && (
          <Button variant="contained" onClick={() => navigate("/add")}>
            ➕ Add Book
          </Button>
        )}
      </Box>

      <Table>
        <TableHead>
          <TableRow>
            <TableCell>Title</TableCell>
            <TableCell>Author</TableCell>
            <TableCell>Published</TableCell>
            <TableCell>Status</TableCell>
            {role === "admin" && <TableCell>Actions</TableCell>}
          </TableRow>
        </TableHead>

        <TableBody>
          {paginatedBooks.map((b) => (
            <TableRow key={b.id}>
              <TableCell>{b.title}</TableCell>
              <TableCell>{b.author}</TableCell>
              <TableCell>{b.publishedDate}</TableCell>
              <TableCell>{b.status}</TableCell>

              {role === "admin" && (
                <TableCell>
                  <Button onClick={() => navigate(`/edit/${b.id}`)}>Edit</Button>
                  <Button
                    color="error"
                    onClick={() => deleteBook(b.id).then(loadBooks)}
                  >
                    Delete
                  </Button>
                </TableCell>
              )}
            </TableRow>
          ))}
        </TableBody>
      </Table>

      <Box sx={{ display: "flex", justifyContent: "center", mt: 3 }}>
        <Pagination
          count={totalPages}
          page={page}
          onChange={(e, val) => setPage(val)}
        />
      </Box>
    </Container>
  );
}
